# Signed netting paths, collateral unit ledgers and frozen default closeout.
.cr_ead_artifact<-function(value,kind){if(inherits(value,'CalcResult'))value<-value$value;if(!.cr_object(value)||!identical(value$artifact_type,kind)) .cr_error('EXPOSURE_ARTIFACT',paste('Expected',kind,'artifact'));frozen<-value;digest<-frozen$artifact_hash;frozen$artifact_hash<-NULL;if(!identical(digest,.cr_hash(frozen))) .cr_error('INTEGRITY_ERROR','Exposure artifact content differs from its binding');value}
.cr_ead_seal<-function(value){value$artifact_hash<-.cr_hash(value);value}
.cr_ead_key<-function(path,date,set) .cr_data_key(list(path=path,date=date,set=set),c('path','date','set'))
.cr_ead_chars<-function(x)if(is.list(x))unlist(x,use.names=FALSE) else x
aggregate_netting_set_exposure<-function(trade_value_paths,netting_agreements,fx_paths,as_of,reporting_currency,valuation_convention,context=NULL){
 ctx<-.cr_lgd_currency(reporting_currency,context);start<-.cr_data_date(as_of,'as_of');if(!identical(valuation_convention,'EX_DIVIDEND_BEFORE_MARGIN')) .cr_error('EXPOSURE_CONVENTION','Declare EX_DIVIDEND_BEFORE_MARGIN trade valuation')
 rows<-.cr_data_rows(trade_value_paths,'trade_value_paths');agreements<-.cr_data_rows(netting_agreements,'netting_agreements');fx<-.cr_data_rows(fx_paths,'fx_paths');if(!length(rows)||!length(agreements)) .cr_error('EMPTY_INPUT','Trade paths and netting agreements required')
 .cr_data_unique(rows,c('path_id','date','trade_id'),'trade_value_paths');.cr_data_unique(agreements,'netting_set_id','netting_agreements');.cr_data_unique(fx,c('path_id','date','currency'),'fx_paths')
 paths<-sort(unique(vapply(rows,`[[`,character(1),'path_id')));dates<-sort(unique(vapply(rows,`[[`,character(1),'date')));trades<-sort(unique(vapply(rows,`[[`,character(1),'trade_id')));membership<-list();metadata<-list()
 for(date in dates)if(.cr_data_date(date,'date')<start) .cr_error('EXPOSURE_DATE','Valuation dates cannot precede as_of')
 for(agreement in agreements){.cr_data_required(agreement,c('counterparty_id','trade_ids','legally_enforceable','evidence_reference','known_at','effective_from'));if(!('effective_until'%in%names(agreement))) .cr_error('NETTING_CONTRACT','Explicit effective_until date or null required');for(k in c('counterparty_id','evidence_reference')) .cr_string(agreement[[k]],k,'NETTING_CONTRACT');members<-.cr_ead_chars(agreement$trade_ids)
  if(!is.character(members)||!length(members)||anyNA(members)||any(!nzchar(members))||anyDuplicated(members)) .cr_error('NETTING_CONTRACT','Distinct nonempty trade membership required')
  if(!is.logical(agreement$legally_enforceable)||length(agreement$legally_enforceable)!=1L||is.na(agreement$legally_enforceable)||(!agreement$legally_enforceable&&length(members)>1L)) .cr_error('NETTING_ELIGIBILITY','Multiple-trade netting requires enforceability evidence; false is allowed only for singleton sets')
  first<-.cr_data_date(agreement$effective_from,'effective_from');last<-if(is.null(agreement$effective_until))NULL else .cr_data_date(agreement$effective_until,'effective_until')
  if(.cr_data_date(agreement$known_at,'known_at')>start||first>.cr_data_date(dates[1],'date')||(!is.null(last)&&last<=.cr_data_date(tail(dates,1),'date'))) .cr_error('NETTING_ELIGIBILITY','Agreement must be known at snapshot and cover every valuation date [from,until)')
  for(trade in members){if(!is.null(membership[[trade]])) .cr_error('NETTING_OVERLAP','A trade cannot belong to multiple sets');membership[[trade]]<-agreement$netting_set_id};agreement$trade_ids<-as.list(members);metadata[[length(metadata)+1L]]<-agreement
 }
 if(!setequal(names(membership),trades)) .cr_error('NETTING_MEMBERSHIP','Every modeled trade must have exactly one declared membership');lookup<-currencies<-list()
 for(row in rows){.cr_data_required(row,c('currency','value'));value<-.cr_lgd_scalar(row$value,'trade value');.cr_string(row$currency,'currency','INVALID_CURRENCY');if(!is.null(currencies[[row$trade_id]])&&!identical(currencies[[row$trade_id]],row$currency)) .cr_error('EXPOSURE_CONVENTION','Trade currency changes require explicit redenomination preprocessing');currencies[[row$trade_id]]<-row$currency;lookup[[.cr_ead_key(row$path_id,row$date,row$trade_id)]]<-value}
 if(length(rows)!=length(paths)*length(dates)*length(trades)) .cr_error('PATH_ALIGNMENT','Complete common path/date/trade grid required');rates<-list()
 for(row in fx){.cr_data_required(row,'rate');rate<-.cr_lgd_scalar(row$rate,'FX rate',0);if(rate<=0||(row$currency==reporting_currency&&rate!=1)) .cr_error('INVALID_FX','Positive FX and exact reporting-currency identity required');rates[[.cr_ead_key(row$path_id,row$date,row$currency)]]<-rate}
 metadata<-metadata[order(vapply(metadata,`[[`,character(1),'netting_set_id'))];output<-list()
 for(path in paths)for(date in dates)for(agreement in metadata){values<-numeric();for(trade in unlist(agreement$trade_ids)){key<-.cr_ead_key(path,date,currencies[[trade]]);if(is.null(rates[[key]])) .cr_error('MISSING_FX','Exact scenario/date/currency FX required');values<-c(values,.cr_loss_multiply(lookup[[.cr_ead_key(path,date,trade)]],rates[[key]]))};net<-.cr_loss_sum(values);output[[length(output)+1L]]<-list(path_id=path,date=date,netting_set_id=agreement$netting_set_id,signed_net_value=net,positive_exposure=max(net,0),gross_positive=.cr_loss_sum(values[values>0]),gross_negative=.cr_loss_sum(values[values<0]))}
 value<-.cr_ead_seal(list(artifact_type='NETTING_PATHS',provenance=.cr_result(NULL,'ead.context',context=ctx)$provenance,as_of=as_of,currency=reporting_currency,valuation_convention=valuation_convention,path_ids=as.list(paths),dates=as.list(dates),netting_agreements=metadata,paths=output))
 .cr_result(value,'ead.aggregate_netting_set_exposure',reporting_currency,ctx,diagnostics=list(input_fingerprint=.cr_hash(list(trade_value_paths=rows,netting_agreements=agreements,fx_paths=fx))),limitations='Enforceability and membership are supplied evidence, not legal determinations. Signed values are aggregated before flooring and never offset across netting sets.')
}
.cr_ead_collateral_market<-function(rows,artifact,policies){rows<-.cr_data_rows(rows,'collateral_market_paths');.cr_data_unique(rows,c('path_id','date','netting_set_id'),'collateral_market_paths');lookup<-list();expected<-unlist(lapply(unlist(artifact$path_ids),function(p)unlist(lapply(unlist(artifact$dates),function(d)vapply(names(policies),function(s).cr_ead_key(p,d,s),character(1))))),use.names=FALSE)
 for(row in rows){.cr_data_required(row,c('unit_price','fx_rate','received_haircut','posted_haircut','currency'));key<-.cr_ead_key(row$path_id,row$date,row$netting_set_id);if(!(key%in%expected)) .cr_error('PATH_ALIGNMENT','Collateral market row outside netting grid');policy<-policies[[row$netting_set_id]];price<-.cr_lgd_scalar(row$unit_price,'collateral unit price',0);fx<-.cr_lgd_scalar(row$fx_rate,'collateral FX',0);hr<-.cr_lgd_scalar(row$received_haircut,'received_haircut',0);hp<-.cr_lgd_scalar(row$posted_haircut,'posted_haircut',0)
 if(price<=0||fx<=0||hr>=1||hp>=1||row$currency!=policy$collateral_currency||(row$currency==artifact$currency&&fx!=1)) .cr_error('COLLATERAL_MARKET','Positive collateral prices/FX and haircuts in [0,1), with matching currency, required');unit_value<-.cr_loss_multiply(price,fx);if(unit_value<=0) .cr_error('NUMERICAL_FAILURE','Collateral unit value underflow');row$unit_reporting_value<-unit_value;lookup[[key]]<-row}
 if(!setequal(names(lookup),expected)) .cr_error('PATH_ALIGNMENT','Complete collateral market grid required');lookup}
.cr_ead_collateral_exposure<-function(value,units,market,policy){nominal<-.cr_loss_multiply(units,market$unit_reporting_value);received<-.cr_loss_multiply(max(nominal,0),1-market$received_haircut);posted<-if(policy$posted_returnability=='BANKRUPTCY_REMOTE')0 else max(-nominal,0);raw<-if(policy$posted_claim_netting_enforceable).cr_loss_sum(c(value,-received,posted)) else .cr_loss_sum(c(max(.cr_loss_sum(c(value,-received)),0),posted));list(collateral_nominal=nominal,recognized_received=received,posted_unsecured_claim=posted,residual_exposure=max(raw,0))}
simulate_collateral_margin<-function(netting_paths,margin_policies,call_calendar,collateral_market_paths,context=NULL){
 artifact<-.cr_ead_artifact(netting_paths,'NETTING_PATHS');ctx<-.cr_lgd_currency(artifact$currency,context);start<-.cr_data_date(artifact$as_of,'as_of');policies<-.cr_data_rows(margin_policies,'margin_policies');.cr_data_unique(policies,'netting_set_id','margin_policies');policy_map<-setNames(policies,vapply(policies,`[[`,character(1),'netting_set_id'))
 if(!setequal(names(policy_map),vapply(artifact$netting_agreements,`[[`,character(1),'netting_set_id'))) .cr_error('NETTING_MEMBERSHIP','Exactly one margin policy per netting set required')
 for(policy in policies){.cr_data_required(policy,c('known_at','collateral_currency','initial_units','threshold_received','threshold_posted','minimum_transfer_amount','ownership','received_enforceable','posted_returnability','posted_claim_netting_enforceable','reuse'));if(.cr_data_date(policy$known_at,'known_at')>start) .cr_error('COLLATERAL_DATE','Margin policy must be known at as_of');.cr_string(policy$collateral_currency,'collateral_currency','INVALID_CURRENCY');.cr_lgd_scalar(policy$initial_units,'initial_units');for(k in c('threshold_received','threshold_posted','minimum_transfer_amount')) .cr_lgd_scalar(policy[[k]],k,0)
 if(!(policy$ownership%in%c('TITLE_TRANSFER','SECURITY_INTEREST'))||!identical(policy$received_enforceable,TRUE)||!(policy$posted_returnability%in%c('UNSECURED_CLAIM','BANKRUPTCY_REMOTE'))||!(policy$reuse%in%c('ALLOWED','PROHIBITED'))) .cr_error('COLLATERAL_OWNERSHIP','Explicit ownership, enforceable received collateral, returnability and reuse terms required');if(!is.logical(policy$posted_claim_netting_enforceable)||length(policy$posted_claim_netting_enforceable)!=1L||is.na(policy$posted_claim_netting_enforceable)) .cr_error('COLLATERAL_OWNERSHIP','Explicit Boolean posted-claim netting enforceability required');if(policy$ownership=='TITLE_TRANSFER'&&policy$posted_returnability=='BANKRUPTCY_REMOTE') .cr_error('COLLATERAL_OWNERSHIP','Title-transferred posted collateral cannot be assumed bankruptcy-remote')}
 market<-.cr_ead_collateral_market(collateral_market_paths,artifact,policy_map);calls<-.cr_data_rows(call_calendar,'call_calendar');.cr_data_unique(calls,'call_id','call_calendar');.cr_data_unique(calls,c('path_id','netting_set_id','call_date'),'call_calendar');call_map<-list()
 for(row in calls){.cr_data_required(row,c('valuation_date','settlement_date','dispute_delay_days'));key<-.cr_ead_key(row$path_id,row$call_date,row$netting_set_id);valuation<-.cr_data_date(row$valuation_date,'valuation_date');call<-.cr_data_date(row$call_date,'call_date');settlement<-.cr_data_date(row$settlement_date,'settlement_date');delay<-.cr_data_days(row$dispute_delay_days,'dispute_delay_days');effective<-settlement+delay;if(!is.finite(as.numeric(effective))||effective>as.Date('9999-12-31')) .cr_error('COLLATERAL_DATE','Effective settlement exceeds the calendar date domain')
 if(is.null(market[[key]])||!(row$valuation_date%in%unlist(artifact$dates))||valuation>call||call>settlement) .cr_error('COLLATERAL_DATE','Calls require known grid valuation no later than call and settlement no earlier than call');if(effective<=.cr_data_date(tail(unlist(artifact$dates),1),'last date')&&!(as.character(effective)%in%unlist(artifact$dates))) .cr_error('PATH_ALIGNMENT','Effective settlement must occur on the explicit grid or after its end');row$effective_settlement_date<-as.character(effective);call_map[[key]]<-row}
 net<-setNames(lapply(artifact$paths,`[[`,'signed_net_value'),vapply(artifact$paths,function(r).cr_ead_key(r$path_id,r$date,r$netting_set_id),character(1)));ledger<-output<-list()
 for(path in unlist(artifact$path_ids))for(set_id in sort(names(policy_map))){policy<-policy_map[[set_id]];units<-policy$initial_units;pending<-list()
 for(date in unlist(artifact$dates)){key<-.cr_ead_key(path,date,set_id);opening<-units;settled<-Filter(function(c)c$effective_settlement_date==date,pending);units<-.cr_loss_sum(c(units,vapply(settled,`[[`,numeric(1),'transfer_units')));pending<-Filter(function(c)c$effective_settlement_date!=date,pending);before_calls<-units;call<-call_map[[key]]
 if(!is.null(call)){vk<-.cr_ead_key(path,call$valuation_date,set_id);v<-net[[vk]];m<-market[[vk]];desired<-if(v>policy$threshold_received)v-policy$threshold_received else if(v< -policy$threshold_posted)v+policy$threshold_posted else 0;divisor<-.cr_loss_multiply(m$unit_reporting_value,1-(if(desired>=0)m$received_haircut else m$posted_haircut));if(divisor<=0) .cr_error('NUMERICAL_FAILURE','Haircut-adjusted collateral unit value underflow');target_units<-desired/divisor;if(!is.finite(target_units)) .cr_error('NUMERICAL_FAILURE','Margin target units outside finite range');committed<-.cr_loss_sum(c(units,vapply(pending,`[[`,numeric(1),'transfer_units')));transfer<-.cr_loss_sum(c(target_units,-committed));transfer_value<-abs(.cr_loss_multiply(transfer,m$unit_reporting_value));execute<-transfer!=0&&transfer_value>=policy$minimum_transfer_amount
 entry<-c(call,list(valuation_net_value=v,target_units=target_units,committed_units=committed,transfer_units=if(execute)transfer else 0,transfer_reporting_value=if(execute)transfer_value else 0,status=if(execute)'CALLED' else 'BELOW_MTA_OR_ZERO'));ledger[[length(ledger)+1L]]<-entry;if(execute){if(call$effective_settlement_date==date)units<-.cr_loss_sum(c(units,transfer)) else pending[[length(pending)+1L]]<-entry}}
 metrics<-.cr_ead_collateral_exposure(net[[key]],units,market[[key]],policy);output[[length(output)+1L]]<-c(list(path_id=path,date=date,netting_set_id=set_id,signed_net_value=net[[key]],opening_units=opening,units_before_calls=before_calls,closing_units=units,pending_units=.cr_loss_sum(vapply(pending,`[[`,numeric(1),'transfer_units'))),metrics)}}
 # Order market records by the public tuple, not by encoded internal lookup keys.
 markets<-unname(market);markets<-markets[order(vapply(markets,`[[`,character(1),'path_id'),vapply(markets,`[[`,character(1),'date'),vapply(markets,`[[`,character(1),'netting_set_id'))]
 value<-.cr_ead_seal(list(artifact_type='COLLATERAL_PATHS',provenance=artifact$provenance,netting_artifact_hash=artifact$artifact_hash,as_of=artifact$as_of,currency=artifact$currency,path_ids=artifact$path_ids,dates=artifact$dates,margin_policies=unname(policy_map[sort(names(policy_map))]),collateral_market_paths=markets,paths=output,call_ledger=ledger,mta_convention='GROSS_REPORTING_MARKET_VALUE',event_order='PRIOR_SETTLEMENTS_THEN_CALL_THEN_IMMEDIATE_SETTLEMENT'))
 .cr_result(value,'ead.simulate_collateral_margin',artifact$currency,ctx,provenance=artifact$provenance,diagnostics=.cr_empty_object(),limitations='Calls use declared valuation dates, with outstanding units included to avoid duplicate calls. Received haircuts reduce recognized collateral; unsegregated posted collateral remains a full nominal return claim. Reuse permissions are recorded but no reinvestment or funding benefit is inferred.')
}
closeout_exposure_at_default<-function(netting_paths,collateral_paths,default_events,intermediate_cashflows,freeze_timing,cashflow_convention,context=NULL){
 net<-.cr_ead_artifact(netting_paths,'NETTING_PATHS');coll<-.cr_ead_artifact(collateral_paths,'COLLATERAL_PATHS');ctx<-.cr_lgd_currency(net$currency,context);if(!identical(coll$netting_artifact_hash,net$artifact_hash)) .cr_error('TARGET_MISMATCH','Collateral and netting path bindings differ')
 if(!(freeze_timing%in%c('BEFORE_DATE_EVENTS','AFTER_DATE_EVENTS'))||!identical(cashflow_convention,'UNSETTLED_EXCLUDED_FROM_CLOSEOUT_VALUE')) .cr_error('CLOSEOUT_CONVENTION','Declare collateral freeze timing and excluded unsettled cashflows')
 events<-.cr_data_rows(default_events,'default_events');.cr_data_unique(events,c('path_id','netting_set_id'),'default_events');flows<-.cr_data_rows(intermediate_cashflows,'intermediate_cashflows');.cr_data_unique(flows,'cashflow_id','intermediate_cashflows');keys<-vapply(events,function(r).cr_data_key(r,c('path_id','netting_set_id')),character(1))
 for(f in flows){.cr_data_required(f,c('path_id','netting_set_id','date','amount','included_in_closeout_value','currency'));.cr_data_date(f$date,'cashflow date');.cr_lgd_scalar(f$amount,'cashflow amount');if(!(.cr_data_key(f,c('path_id','netting_set_id'))%in%keys)||f$currency!=net$currency||!identical(f$included_in_closeout_value,FALSE)) .cr_error('CLOSEOUT_CASHFLOW','Cashflows must refer to a modeled default in reporting currency and be explicitly excluded from closeout values')}
 map<-function(rows)setNames(rows,vapply(rows,function(r).cr_ead_key(r$path_id,r$date,r$netting_set_id),character(1)));nlookup<-map(net$paths);clookup<-map(coll$paths);policies<-setNames(coll$margin_policies,vapply(coll$margin_policies,`[[`,character(1),'netting_set_id'));market<-map(coll$collateral_market_paths);output<-list()
 for(event in events){.cr_data_required(event,c('default_date','closeout_date','margin_observation_date'));observation<-.cr_data_date(event$margin_observation_date,'margin_observation_date');default<-.cr_data_date(event$default_date,'default_date');closeout<-.cr_data_date(event$closeout_date,'closeout_date');dk<-.cr_ead_key(event$path_id,event$default_date,event$netting_set_id);ck<-.cr_ead_key(event$path_id,event$closeout_date,event$netting_set_id);if(closeout<default||observation>default) .cr_error('CLOSEOUT_DATE','Require margin observation no later than default and closeout no earlier than default');if(is.null(nlookup[[dk]])||is.null(nlookup[[ck]])) .cr_error('INSUFFICIENT_PATH_EXTENSION','Default and closeout require exact dates on the extended market/collateral grid');units<-clookup[[dk]][[if(freeze_timing=='BEFORE_DATE_EVENTS')'opening_units' else 'closing_units']];selected<-Filter(function(f)f$path_id==event$path_id&&f$netting_set_id==event$netting_set_id,flows)
 if(any(vapply(selected,function(f){d<-.cr_data_date(f$date,'date');d<=default||d>closeout},logical(1)))) .cr_error('CLOSEOUT_CASHFLOW','Unsettled flows must lie in (default,closeout]');cash<-.cr_loss_sum(vapply(selected,`[[`,numeric(1),'amount'));value<-.cr_loss_sum(c(nlookup[[ck]]$signed_net_value,cash));metrics<-.cr_ead_collateral_exposure(value,units,market[[ck]],policies[[event$netting_set_id]]);exposure<-metrics$residual_exposure;metrics$residual_exposure<-NULL
 output[[length(output)+1L]]<-c(list(path_id=event$path_id,netting_set_id=event$netting_set_id,default_date=event$default_date,closeout_date=event$closeout_date,margin_observation_date=event$margin_observation_date,margin_period_days=as.numeric(closeout-observation),default_to_closeout_days=as.numeric(closeout-default),closeout_net_value=nlookup[[ck]]$signed_net_value,unsettled_contractual_cashflows=cash,frozen_collateral_units=units,closeout_exposure=exposure),metrics)}
 .cr_result(list(currency=net$currency,freeze_timing=freeze_timing,cashflow_convention=cashflow_convention,closeouts=output),'ead.closeout_exposure_at_default',net$currency,ctx,provenance=net$provenance,diagnostics=list(netting_artifact_hash=net$artifact_hash,collateral_artifact_hash=coll$artifact_hash),limitations='Margin after the freeze cannot reduce closeout exposure. Frozen units are revalued at closeout market/FX/haircut; no path extrapolation or accrued funding interest is invented. Signed intervening unsettled claims are included exactly once.')
}
